    "d.a2-05.3": "Celle sur l'histoire ? Je connaissais la réponse, je crois.",
    "d.a2-05.4": "J'ai étudié toute la nuit, mais j'ai oublié les dates.",
    "d.a2-05.5": "Tu es allée au cours lundi ? Le professeur a tout expliqué.",
    "d.a2-05.6": "Non, j'étais malade et j'avais un rendez-vous chez le médecin.",
    "d.a2-05.7": "Je peux te donner mon cahier. Il y a toutes les réponses.",
    "d.a2-05.8": "Merci ! Tu as fait beaucoup d'erreurs ?",
    "d.a2-05.9": "Deux ou trois, je crois. La partie mathématiques était facile.",
    "d.a2-05.10": "Facile pour toi ! Quand est-ce qu'on a les notes ?",
    "d.a2-05.11": "La semaine prochaine. Allez, on va à la bibliothèque.",
    "m.a2-05": "À l'école, j'aimais ... , mais ... était difficile. La semaine dernière, je suis allé à ... et j'ai appris ... . J'ai fait ... erreurs. Je n'ai pas compris ... .",

