    "w.a2-06.fashion": "la mode",
    "p.a2-06.1": "Qu'est-ce que tu mets pour la fête ?",
    "p.a2-06.2": "Je peux l'essayer ?",
    "p.a2-06.3": "Ça te va très bien.",
    "p.a2-06.4": "C'est trop grand pour moi.",
    "p.a2-06.5": "Il est comment ?",
    "p.a2-06.6": "Elle a de longs cheveux foncés.",
    "p.a2-06.7": "Il est plus grand que moi.",
    "p.a2-06.8": "Celui-ci est meilleur que celui-là.",
    "p.a2-06.9": "C'est la femme la plus élégante du bureau.",
    "p.a2-06.10": "Il porte des lunettes.",
    "p.a2-06.11": "Prends un manteau, il fait froid dehors.",
    "p.a2-06.12": "Tu es superbe !",
    "s.a2-06.1": "Aujourd'hui, je porte un jean, un tee-shirt blanc et une veste.",
    "s.a2-06.2": "Ma sœur est plus petite que moi, mais elle est plus forte.",
    "s.a2-06.3": "Cette robe est plus élégante que la jupe.",
    "s.a2-06.4": "C'est un homme grand et mince, avec des cheveux blonds et des lunettes.",
    "s.a2-06.5": "Ces chaussures sont meilleures que celles-là, mais plus chères.",
    "s.a2-06.6": "En hiver, nous portons un manteau, un chapeau et une écharpe.",
    "s.a2-06.7": "Ma grand-mère est la personne la plus gentille de la famille.",
    "s.a2-06.8": "J'ai essayé le pantalon, mais il ne m'allait pas.",
    "s.a2-06.9": "Le temps aujourd'hui est pire qu'hier.",
    "s.a2-06.10": "Les chaussettes noires sont moins chères que les rouges.",
    "s.a2-06.11": "Elle aime la mode et porte toujours de beaux vêtements.",
    "s.a2-06.12": "Mon frère est le plus beau garçon de sa classe.",
    "d.a2-06.1": "Michal, qui est la femme à côté de ton chef ?",
    "d.a2-06.2": "Laquelle ? La grande avec les longs cheveux foncés ?",
    "d.a2-06.3": "Non, la plus petite, avec des lunettes et une robe rouge.",
    "d.a2-06.4": "Ah, c'est Dana, notre nouvelle collègue. Elle est très gentille.",
    "d.a2-06.5": "Elle est très élégante. J'aime bien sa veste.",
    "d.a2-06.6": "Oui, elle adore la mode. Elle porte toujours de plus beaux vêtements que moi !",
    "d.a2-06.7": "Et qui est l'homme aux cheveux blonds avec la chemise bleue ?",
    "d.a2-06.8": "C'est son mari. Il est plus âgé qu'elle, je crois.",
    "d.a2-06.9": "Il a l'air d'être quelqu'un de sympathique.",
    "d.a2-06.10": "Il l'est. Viens, je te présente.",
    "m.a2-06": "Mon ami ... est grand / petit et il a les cheveux ... . D'habitude, il porte ... . Il est plus grand que moi, mais je suis plus ... que lui. C'est la personne la plus ... que je connaisse.",

