    "w.a2-07.famous": "célèbre",
    "p.a2-07.1": "Devine ce qui m'est arrivé !",
    "p.a2-07.2": "Il était une fois...",
    "p.a2-07.3": "Et qu'est-ce qui s'est passé ensuite ?",
    "p.a2-07.4": "Soudain, la lumière s'est éteinte.",
    "p.a2-07.5": "Je suis né en 1990.",
    "p.a2-07.6": "J'ai grandi dans un petit village.",
    "p.a2-07.7": "Heureusement, personne n'a été blessé.",
    "p.a2-07.8": "Tu plaisantes !",
    "p.a2-07.9": "Je n'arrivais pas à y croire.",
    "p.a2-07.10": "À la fin, tout s'est bien passé.",
    "p.a2-07.11": "Pendant que je dormais, le téléphone a sonné.",
    "p.a2-07.12": "Raconte-moi toute l'histoire.",
    "s.a2-07.1": "Quand j'étais enfant, nous habitions près de la mer.",
    "s.a2-07.2": "D'abord j'ai perdu mes clés, puis je les ai trouvées dans mon sac.",
    "s.a2-07.3": "Pendant que nous mangions, mon frère a raconté une longue histoire.",
    "s.a2-07.4": "Soudain, elle est tombée et s'est cassé le bras.",
    "s.a2-07.5": "Mes parents se sont mariés il y a trente ans.",
    "s.a2-07.6": "Il a dit qu'il avait vu une personne célèbre à l'aéroport.",
    "s.a2-07.7": "Nous avons gagné et tout le monde a ri et chanté.",
    "s.a2-07.8": "Il y a eu un accident sur la route, mais heureusement personne n'a été blessé.",
    "s.a2-07.9": "C'était une aventure merveilleuse du début à la fin.",
    "s.a2-07.10": "Malheureusement, quand nous sommes arrivés, la fête était déjà finie.",
    "s.a2-07.11": "Le bébé a pleuré toute la nuit, et nous sommes encore fatigués.",
    "s.a2-07.12": "À ce moment-là, j'ai compris que c'était une fête surprise.",
    "d.a2-07.1": "Mamie, raconte-moi une histoire de ton enfance.",
    "d.a2-07.2": "Une fois, quand j'avais huit ans, je suis allée à la plage avec mon frère.",
    "d.a2-07.3": "Seulement vous deux ? Sans vos parents ?",
    "d.a2-07.4": "Oui ! Pendant que nous nagions, il a soudain commencé à pleuvoir.",
    "d.a2-07.5": "Et qu'est-ce qui s'est passé ensuite ?",
    "d.a2-07.6": "Nous avons couru à la maison, mais je suis tombée et j'ai perdu une chaussure.",
    "d.a2-07.7": "Oh non ! Tu l'as retrouvée ?",
    "d.a2-07.8": "Non, malheureusement. Ma mère était en colère, mais ensuite elle a ri.",
    "d.a2-07.9": "Et ton frère ?",
    "d.a2-07.10": "Il raconte encore cette histoire à chaque dîner de famille !",
    "d.a2-07.11": "J'adore tes histoires, Mamie.",
    "m.a2-07": "... dernier, j'étais ... quand soudain ... . D'abord j'ai ... , puis j'ai ... . Heureusement, ... . À la fin, ... .",

