    "p.a2-08.1": "Qu'est-ce que tu fais le week-end prochain ?",
    "p.a2-08.2": "Je vais rendre visite à mes parents.",
    "p.a2-08.3": "Tu veux venir à mon anniversaire ?",
    "p.a2-08.4": "Avec plaisir !",
    "p.a2-08.5": "Désolé, je ne peux pas. J'ai d'autres projets.",
    "p.a2-08.6": "Peut-être la prochaine fois.",
    "p.a2-08.7": "À bientôt !",
    "p.a2-08.8": "J'espère.",
    "p.a2-08.9": "Qu'est-ce que tu feras après la formation ?",
    "p.a2-08.10": "Je t'appellerai plus tard.",
    "p.a2-08.11": "Tu es prêt ?",
    "p.a2-08.12": "C'est promis !",
    "s.a2-08.1": "L'année prochaine, je vais étudier à l'étranger.",
    "s.a2-08.2": "S'il pleut demain, nous resterons à la maison.",
    "s.a2-08.3": "Ma sœur se mariera en juin ; nous organisons le mariage.",
    "s.a2-08.4": "Ils vont bientôt déménager dans un appartement plus grand.",
    "s.a2-08.5": "J'économise de l'argent parce que je veux voyager au Japon.",
    "s.a2-08.6": "Nous fêterons probablement son anniversaire au restaurant.",
    "s.a2-08.7": "Elle a décidé de devenir médecin quand elle avait dix ans.",
    "s.a2-08.8": "Tu viendras au concert avec nous vendredi ?",
    "s.a2-08.9": "Mon rêve est d'avoir ma propre entreprise un jour.",
    "s.a2-08.10": "Je promets que j'essaierai d'arriver tôt.",
    "s.a2-08.11": "Quelle est la date du mariage ? Le vingt mai.",
    "s.a2-08.12": "Il est impossible de finir le projet cette semaine.",
    "d.a2-08.1": "Nir, qu'est-ce que tu fais samedi prochain ?",
    "d.a2-08.2": "Je ne sais pas encore. Pourquoi ?",
    "d.a2-08.3": "C'est mon anniversaire et je vais faire une fête à la maison. Tu veux venir ?",
    "d.a2-08.4": "Avec plaisir ! À quelle heure ?",
    "d.a2-08.5": "À huit heures. Je vais cuisiner, et Maya apportera la musique.",
    "d.a2-08.6": "Super. Je peux apporter quelque chose ?",
    "d.a2-08.7": "Peut-être un gâteau ? Si tu as le temps.",
    "d.a2-08.8": "Certainement. Je ferai un gâteau au chocolat. Combien de personnes viennent ?",
    "d.a2-08.9": "Probablement quinze. Et le mois prochain, on va encore fêter quelque chose : le mariage de ma sœur !",
    "d.a2-08.10": "Waouh, félicitations ! Alors à samedi.",
    "m.a2-08": "... prochain, je vais ... . Je vais probablement ... . Si j'ai le temps, je ... . Mon rêve est de ... . J'espère ... bientôt.",

