    "w.a2-09.important": "important",
    "p.a2-09.1": "Comment tu te sens ?",
    "p.a2-09.2": "Je suis de bonne humeur aujourd'hui.",
    "p.a2-09.3": "À mon avis, c'est une bonne idée.",
    "p.a2-09.4": "Je suis d'accord avec toi.",
    "p.a2-09.5": "Je ne suis pas d'accord.",
    "p.a2-09.6": "Je pense que tu as raison.",
    "p.a2-09.7": "Ne t'inquiète pas !",
    "p.a2-09.8": "Qu'est-ce qui ne va pas ?",
    "p.a2-09.9": "Calme-toi.",
    "p.a2-09.10": "Ça me semble bizarre.",
    "p.a2-09.11": "Vraiment ? Je n'y crois pas !",
    "p.a2-09.12": "Ce n'est pas vrai.",
    "s.a2-09.1": "Je suis très heureuse parce que ma sœur vient me rendre visite.",
    "s.a2-09.2": "Il se met en colère quand le train est en retard.",
    "s.a2-09.3": "Ma mère s'inquiète quand je rentre tard le soir.",
    "s.a2-09.4": "Nous nous sommes beaucoup amusés à la fête samedi.",
    "s.a2-09.5": "Elle était nerveuse avant l'entretien, mais elle est calme maintenant.",
    "s.a2-09.6": "À mon avis, le film était bizarre et trop long.",
    "s.a2-09.7": "Les enfants s'ennuient quand il pleut toute la journée.",
    "s.a2-09.8": "Ils sont tombés amoureux pendant un voyage en Italie.",
    "s.a2-09.9": "Je pense que la santé est plus importante que l'argent.",
    "s.a2-09.10": "Il se plaint toujours du temps, mais aujourd'hui je suis d'accord avec lui.",
    "s.a2-09.11": "J'étais surpris et fier quand mon fils a réussi l'examen.",
    "s.a2-09.12": "Elle se sent seule et triste dans la nouvelle ville.",
    "d.a2-09.1": "Keren, tu as l'air triste. Qu'est-ce qui ne va pas ?",
    "d.a2-09.2": "Je suis inquiète. Mon entreprise veut que je déménage dans une autre ville.",
    "d.a2-09.3": "Vraiment ? Et qu'est-ce que tu en penses ?",
    "d.a2-09.4": "Je ne sais pas. Le poste est meilleur, mais je vais me sentir seule là-bas.",
    "d.a2-09.5": "À mon avis, c'est une très belle occasion.",
    "d.a2-09.6": "Peut-être, mais j'ai peur des changements.",
    "d.a2-09.7": "Tout le monde est nerveux au début. Ensuite, on s'amuse et on rencontre de nouvelles personnes.",
    "d.a2-09.8": "C'est vrai. Mon copain est d'accord avec toi, bien sûr.",
    "d.a2-09.9": "Ne t'inquiète pas autant. Réfléchis-y calmement.",
    "d.a2-09.10": "Tu as raison. Merci, Amir. Je me sens déjà plus calme.",
    "m.a2-09": "Aujourd'hui, je me sens ... parce que ... . Je me mets en colère quand ... . À mon avis, ... est ... . Je pense que ... . Je suis / je ne suis pas d'accord avec ... .",

