    "s.a2-10.1": "J'appelle ma grand-mère tous les dimanches, mais elle ne répond jamais.",
    "s.a2-10.2": "Mon ordinateur portable est en panne, donc je travaille sur mon téléphone.",
    "s.a2-10.3": "Elle m'a envoyé une vidéo et je l'ai partagée avec mes amis.",
    "s.a2-10.4": "Bien que l'hôtel ait le wifi, l'internet est très lent.",
    "s.a2-10.5": "J'ai téléchargé l'application, mais j'ai oublié mon mot de passe.",
    "s.a2-10.6": "Il publie des photos sur les réseaux sociaux tous les jours.",
    "s.a2-10.7": "Recharge l'appareil photo avant le voyage, s'il te plaît.",
    "s.a2-10.8": "J'ai reçu votre e-mail ; cependant, je ne peux pas ouvrir le fichier.",
    "s.a2-10.9": "Allume l'ordinateur et recherche le site web.",
    "s.a2-10.10": "Mes parents sont en ligne maintenant, donc je peux les appeler.",
    "s.a2-10.11": "L'écran est noir parce que la batterie est vide.",
    "s.a2-10.12": "Je lui ai écrit hier, mais elle n'a pas encore répondu.",
    "d.a2-10.1": "Allô, Ori ? C'est Tal.",
    "d.a2-10.2": "Salut Tal ! Je t'entends mal. Tu es où ?",
    "d.a2-10.3": "Dans le train. Internet ici est terrible.",
    "d.a2-10.4": "D'accord. Tu as reçu l'e-mail avec les photos du voyage ?",
    "d.a2-10.5": "Oui, je les ai téléchargées, mais je n'arrive pas à ouvrir la vidéo.",
    "d.a2-10.6": "Bizarre. Je te la renvoie par message.",
    "d.a2-10.7": "Merci. Et ne publie pas la photo de moi à la plage sur les réseaux sociaux !",
    "d.a2-10.8": "Même si c'est une super photo ? D'accord, d'accord.",
    "d.a2-10.9": "Écoute, ma batterie est presque à plat. Je te rappelle ce soir.",
    "d.a2-10.10": "D'accord. Recharge ton téléphone ! Salut.",
    "m.a2-10": "J'utilise mon téléphone pour ... et ... . Hier, mon ... était en panne, donc j'ai ... . Bien que ... , je ... . J'ai envoyé ... à ... et ils ont répondu ... .",

