    "p.b1-01.1": "Tu as vu le dernier épisode ?",
    "p.b1-01.2": "Je te le recommande vivement.",
    "p.b1-01.3": "Les critiques étaient partagées.",
    "p.b1-01.4": "C'est tiré d'une histoire vraie.",
    "p.b1-01.5": "Qu'est-ce qu'il y a ce soir ?",
    "p.b1-01.6": "Je n'arrivais pas à m'arrêter de regarder.",
    "p.b1-01.7": "La fin était décevante.",
    "p.b1-01.8": "Regardons-le avec les sous-titres.",
    "p.b1-01.9": "Les billets se sont vendus en une heure.",
    "p.b1-01.10": "Ce n'est pas vraiment mon genre.",
    "p.b1-01.11": "Le public leur a fait une standing ovation.",
    "s.b1-01.1": "Je n'ai jamais vu un documentaire aussi fascinant.",
    "s.b1-01.2": "La série a été diffusée sur une nouvelle chaîne l'année dernière.",
    "s.b1-01.3": "Les critiques ont écrit d'excellentes critiques sur le spectacle.",
    "s.b1-01.4": "Tu t'es déjà abonné à leur chaîne ?",
    "s.b1-01.5": "L'intrigue du film était difficile à suivre.",
    "s.b1-01.6": "L'exposition a ouvert la semaine dernière et a attiré des foules immenses.",
    "s.b1-01.7": "Le personnage principal change beaucoup au cours de la série.",
    "s.b1-01.8": "Le journaliste a interviewé la célébrité après la première.",
    "s.b1-01.9": "Le public a applaudi pendant dix minutes à la fin.",
    "s.b1-01.10": "Beaucoup de jeunes préfèrent regarder les films avec des sous-titres.",
    "s.b1-01.11": "L'exposition célèbre le patrimoine culturel de la région.",
    "d.b1-01.1": "Tu as vu la nouvelle série dont tout le monde parle ?",
    "d.b1-01.2": "Pas encore. J'ai seulement lu une critique dans le journal.",
    "d.b1-01.3": "Les critiques l'ont adorée, surtout le personnage principal.",
    "d.b1-01.4": "L'intrigue est compliquée ? Je suis trop fatigué pour quelque chose de lourd.",
    "d.b1-01.5": "Pas du tout, c'est divertissant et les épisodes sont courts.",
    "d.b1-01.6": "Quelle chaîne la diffuse ?",
    "d.b1-01.7": "Aucune. Il faut s'abonner à un service de streaming.",
    "d.b1-01.8": "Bon. Il y a des sous-titres en hébreu ?",
    "d.b1-01.9": "Oui, et la bande originale est un chef-d'œuvre.",
    "d.b1-01.10": "Tu m'as convaincu. Regardons le premier épisode ce soir.",
