    "p.b1-02.10": "Nous avons été surpris par une tempête au retour.",
    "p.b1-02.11": "Passer à l'énergie solaire a du sens ici.",
    "s.b1-02.1": "Pendant que nous faisions de la randonnée, nous avons vu une famille de cerfs.",
    "s.b1-02.2": "Les glaciers fondaient plus vite que les scientifiques ne l'avaient prévu.",
    "s.b1-02.3": "Mon grand-père plantait un arbre chaque printemps.",
    "s.b1-02.4": "La sécheresse a détruit la plus grande partie de la récolte l'été dernier.",
