    "s.b1-06.9": "Les bonnes habitudes sont plus faciles à garder quand on commence petit.",
    "s.b1-06.10": "Il a dit que la blessure mettrait six semaines à guérir.",
    "s.b1-06.11": "La santé mentale est aussi importante que la forme physique.",
    "s.b1-06.12": "Un exercice modéré améliore l'endurance et le bien-être.",
    "d.b1-06.1": "Comment s'est passé ton bilan de santé ?",
    "d.b1-06.2": "Bien, dans l'ensemble. Le médecin a dit que ma tension était légèrement élevée.",
