    "d.b1-06.9": "On commencera doucement et on s'étirera bien. L'endurance vient avec le temps.",
    "d.b1-06.10": "D'accord. Je veux aussi essayer la méditation pour mon insomnie.",
    "d.b1-06.11": "Bonne idée. Les petites habitudes font une grande différence.",
