    "p.b2-01.7": "Apprendre par cœur, ce n'est pas la même chose que comprendre.",
    "p.b2-01.8": "Elle a obtenu une bourse complète.",
    "p.b2-01.9": "À moins de vous inscrire d'ici vendredi, vous perdrez votre place.",
