    "p.b2-01.11": "C'est en forgeant qu'on devient forgeron.",
    "s.b2-01.1": "Si j'avais reçu une bourse, j'aurais étudié à l'étranger.",
    "s.b2-01.2": "J'aimerais que le programme comporte plus d'esprit critique.",
