    "s.b2-01.10": "Le tuteur a suggéré que nous mémorisions moins et que nous comprenions davantage.",
    "s.b2-01.11": "La curiosité est la meilleure motivation pour acquérir des connaissances.",
    "s.b2-01.12": "L'éducation est obligatoire jusqu'à dix-huit ans dans de nombreux pays.",
    "d.b2-01.1": "Vous vouliez parler de vos options pour l'année prochaine ?",
