    "w.b2-02.to-observe": "observer",
    "w.b2-02.phenomenon": "le phénomène",
    "w.b2-02.to-predict": "prédire",
    "w.b2-02.accurate": "précis",
    "w.b2-02.to-prove": "prouver",
    "w.b2-02.to-conduct": "mener",
    "w.b2-02.cybersecurity": "la cybersécurité",
    "w.b2-02.to-hack": "pirater",
    "w.b2-02.obsolete": "obsolète",
    "w.b2-02.cutting-edge": "de pointe",
    "p.b2-02.1": "Les résultats parlent d'eux-mêmes.",
    "p.b2-02.2": "En théorie, ça marche, mais en pratique, c'est compliqué.",
    "p.b2-02.3": "C'est encore au stade expérimental.",
    "p.b2-02.4": "Les données n'appuient pas cette conclusion.",
    "p.b2-02.5": "En cas de doute, refaites le test.",
    "p.b2-02.6": "La technologie est une arme à double tranchant.",
    "p.b2-02.7": "Mon téléphone est pratiquement obsolète.",
    "p.b2-02.8": "Sauvegarde tes fichiers au cas où le système plante.",
    "p.b2-02.9": "Personne n'aurait pu prédire cela.",
    "p.b2-02.10": "Les scientifiques sont au bord d'une percée.",
    "p.b2-02.11": "Tant que c'est sécurisé, ça ne me dérange pas de l'utiliser.",
    "s.b2-02.1": "Si on chauffe l'eau à cent degrés, elle bout.",
    "s.b2-02.2": "Si l'expérience réussit, l'équipe publiera les données l'année prochaine.",
    "s.b2-02.3": "Si les scientifiques avaient plus de financement, ils mèneraient plus d'expériences.",
    "s.b2-02.4": "Si le satellite n'avait pas été lancé, nous n'aurions pas observé le phénomène.",
    "s.b2-02.5": "À moins que l'algorithme ne soit précis, les prédictions sont inutiles.",
    "s.b2-02.6": "Si l'hypothèse avait été prouvée, elle aurait complètement changé la théorie.",
    "s.b2-02.7": "L'intelligence artificielle peut analyser des données plus vite que n'importe quel humain.",
    "s.b2-02.8": "La percée dans la recherche génétique a été réalisée dans un petit laboratoire.",
    "s.b2-02.9": "Si des pirates s'étaient introduits dans le système, des millions de comptes seraient en danger.",
    "s.b2-02.10": "L'automatisation rendra de nombreux emplois obsolètes d'ici dix ans.",
    "s.b2-02.11": "Les scientifiques ont mesuré les particules avec des instruments de pointe.",
    "s.b2-02.12": "Si j'étais scientifique, j'étudierais comment les cellules se réparent.",
    "d.b2-02.1": "Docteur Adler, votre équipe a annoncé une percée la semaine dernière. Qu'avez-vous découvert exactement ?",
    "d.b2-02.2": "Nous avons développé un algorithme qui prédit comment certaines cellules réagissent à de nouveaux médicaments.",
    "d.b2-02.3": "Quelle est sa précision ?",
    "d.b2-02.4": "Dans nos expériences, environ quatre-vingt-dix pour cent. Si les données sont bonnes, les prédictions sont fiables.",
    "d.b2-02.5": "Que se passerait-il si un hôpital s'y fiait et qu'il se trompait ?",
    "d.b2-02.6": "C'est pourquoi les médecins prendront toujours la décision finale. L'outil ne fait que les assister.",
    "d.b2-02.7": "Certains craignent que l'intelligence artificielle rende les scientifiques obsolètes.",
    "d.b2-02.8": "Si c'était vrai, nous aurions arrêté d'embaucher des chercheurs. Au lieu de cela, nous en avons embauché dix de plus.",
    "d.b2-02.9": "Et la cybersécurité ? Les données des patients sont sensibles.",
    "d.b2-02.10": "À moins que les données ne soient chiffrées et stockées localement, nous ne les utilisons pas.",
    "d.b2-02.11": "Quelle est la prochaine étape pour le laboratoire ?",
    "d.b2-02.12": "Si nous obtenons un financement, nous mènerons un essai plus large au printemps prochain.",
    "m.b2-02": "Une invention qui a changé le monde est ... . Elle a été développée par ... en ... . Si elle n'avait pas été inventée, ... . Aujourd'hui, on l'utilise pour ... . À l'avenir, si ..., elle pourrait ... .",

