    "w.b2-03.forecast": "la prévision",
    "w.b2-03.to-expand": "se développer",
    "w.b2-03.efficiency": "l'efficacité",
    "p.b2-03.1": "Les affaires sont florissantes.",
    "p.b2-03.2": "Nous travaillons à perte.",
    "p.b2-03.3": "Les prix ont explosé.",
    "p.b2-03.4": "Passons aux choses sérieuses.",
    "p.b2-03.5": "L'entreprise a fait faillite l'année dernière.",
    "p.b2-03.6": "La demande dépasse l'offre en ce moment.",
    "p.b2-03.7": "C'est un investissement risqué, mais les rendements pourraient être élevés.",
    "p.b2-03.8": "D'une part..., d'autre part...",
    "p.b2-03.9": "Nous devons réduire les coûts à tous les niveaux.",
    "p.b2-03.10": "L'accord a échoué à la dernière minute.",
    "p.b2-03.11": "À long terme, ce sera rentable.",
    "p.b2-03.12": "Notre part de marché a doublé.",
    "s.b2-03.1": "L'inflation a fortement augmenté ; par conséquent, les consommateurs ont moins dépensé.",
    "s.b2-03.2": "La start-up a lancé une nouvelle marque ; cependant, les ventes sont restées faibles.",
    "s.b2-03.3": "Bien que l'économie soit en croissance, beaucoup de familles ont encore du mal.",
    "s.b2-03.4": "La fusion réduira les coûts ; de plus, elle améliorera l'efficacité.",
    "s.b2-03.5": "Tout d'abord, nous avons besoin d'investisseurs ; deuxièmement, nous avons besoin d'un budget réaliste.",
    "s.b2-03.6": "Le pays exporte de la technologie, tandis qu'il importe la plus grande partie de sa nourriture.",
    "s.b2-03.7": "Malgré la récession, l'entreprise a réalisé un petit bénéfice.",
    "s.b2-03.8": "La prévision annonce une croissance lente ; par conséquent, nous devrions nous développer prudemment.",
    "s.b2-03.9": "Le cours des actions a chuté après la faillite du plus grand fournisseur.",
    "s.b2-03.10": "La concurrence maintient les prix bas, ce qui profite aux consommateurs au bout du compte.",
    "s.b2-03.11": "L'entrepreneuse a financé le projet avec ses propres économies.",
    "s.b2-03.12": "Enfin, rappelez-vous que tout accord comporte un certain risque.",
    "d.b2-03.1": "Merci de m'accorder votre temps. Notre start-up fabrique des emballages réutilisables pour les restaurants.",
    "d.b2-03.2": "Intéressant. Comment se présente la demande ?",
    "d.b2-03.3": "Forte et croissante. Tout d'abord, de nouvelles réglementations interdisent le plastique à usage unique ; deuxièmement, les consommateurs préfèrent les marques durables.",
    "d.b2-03.4": "Cependant, vos coûts de production semblent élevés. Comment ferez-vous des bénéfices ?",
    "d.b2-03.5": "Au début, nous travaillerons à légère perte. Dès que nous nous développerons, l'efficacité s'améliorera et les coûts baisseront.",
    "d.b2-03.6": "Et la concurrence ? Il y a de plus grandes entreprises sur ce marché.",
    "d.b2-03.7": "C'est vrai, mais elles importent leurs produits, tandis que nous fabriquons localement et livrons plus vite.",
    "d.b2-03.8": "Quel financement recherchez-vous ?",
    "d.b2-03.9": "Deux millions, en échange de quinze pour cent des actions.",
    "d.b2-03.10": "C'est ambitieux. De plus, la prévision suppose qu'il n'y aura pas de récession.",
    "d.b2-03.11": "Nous avons préparé un second budget pour une économie plus lente. Le voici.",
    "d.b2-03.12": "Bien. Envoyez-moi le plan complet et nous en parlerons la semaine prochaine.",
    "m.b2-03": "L'économie de ... est actuellement ... . Tout d'abord, ... . Par conséquent, ... . Cependant, ... . De plus, ... . Donc, à long terme, ... .",

