    "w.b2-04.playwright": "le dramaturge",
    "w.b2-04.tragedy": "la tragédie",
    "p.b2-04.1": "C'est ouvert à l'interprétation.",
    "p.b2-04.2": "Le roman a été un best-seller immédiat.",
    "p.b2-04.3": "Je n'arrivais pas à lâcher le livre.",
    "p.b2-04.4": "Le tableau m'a profondément marqué.",
    "p.b2-04.5": "La mélodie m'est restée en tête pendant des jours.",
    "p.b2-04.6": "Elle a une imagination débordante.",
    "p.b2-04.7": "L'exposition vaut vraiment le détour.",
    "p.b2-04.8": "Que veut dire l'auteur par là ?",
    "p.b2-04.9": "La fin m'a complètement pris par surprise.",
    "p.b2-04.10": "L'art est une question de goût.",
    "p.b2-04.11": "Les paroles sont plus importantes que la musique.",
    "s.b2-04.1": "La publication de son premier roman a changé sa vie.",
    "s.b2-04.2": "La représentation de la pauvreté dans le film est d'un réalisme douloureux.",
    "s.b2-04.3": "L'interprétation de la sculpture par le conservateur a surpris de nombreux visiteurs.",
    "s.b2-04.4": "La solitude du protagoniste est le thème central du roman.",
    "s.b2-04.5": "La composition de la symphonie a pris près de dix ans au compositeur.",
    "s.b2-04.6": "Le poète utilise la mer comme métaphore de la mémoire.",
    "s.b2-04.7": "L'arrivée du chef d'orchestre sur scène a été accueillie par de vifs applaudissements.",
    "s.b2-04.8": "L'art abstrait exige la participation active du spectateur.",
    "s.b2-04.9": "Le manque de fiabilité du narrateur donne à l'histoire sa tension.",
    "s.b2-04.10": "Le portrait révèle la tristesse derrière le sourire du roi.",
    "s.b2-04.11": "Le dramaturge a trouvé l'inspiration dans une tragédie grecque antique.",
    "s.b2-04.12": "La décision de la galerie d'exposer de jeunes artistes a été largement saluée.",
    "d.b2-04.1": "Alors, qu'avez-vous pensé du roman ?",
    "d.b2-04.2": "Honnêtement, j'ai eu du mal à aimer le protagoniste, mais l'écriture est magnifique.",
    "d.b2-04.3": "Je suis d'accord pour l'écriture. L'usage que l'auteure fait de la métaphore est remarquable.",
    "d.b2-04.4": "La rivière qui revient sans cesse, par exemple. Est-ce une métaphore du temps ?",
    "d.b2-04.5": "C'est une interprétation. Moi, je l'ai lue comme la culpabilité du narrateur.",
    "d.b2-04.6": "Intéressant. Le thème de la culpabilité traverse effectivement tout le livre.",
    "d.b2-04.7": "Tu savais qu'il est adapté pour la scène par un dramaturge connu ?",
    "d.b2-04.8": "Vraiment ? Je me demande comment ils vont dépeindre les scènes de rêve.",
    "d.b2-04.9": "Probablement avec de la musique. L'auteure a dit que le rythme comptait plus pour elle que l'intrigue.",
    "d.b2-04.10": "Ça explique pourquoi ça se lit comme de la poésie par endroits.",
    "d.b2-04.11": "On choisit quelque chose de plus léger pour le mois prochain ?",
    "d.b2-04.12": "Oui, s'il te plaît. Une comédie, ou au moins pas une autre tragédie.",
    "m.b2-04": "L'exposition offre une représentation rare de ... . Le choix de ... par le conservateur crée ... . Particulièrement intéressant est ... . La combinaison de ... et de ... produit ... . Dans l'ensemble, ... .",

