    "w.b2-05.investigation": "l'enquête",
    "p.b2-05.1": "Innocent jusqu'à preuve du contraire.",
    "p.b2-05.2": "Il a nié toutes les accusations.",
    "p.b2-05.3": "Le jury a rendu son verdict.",
    "p.b2-05.4": "Je vous traînerai en justice.",
    "p.b2-05.5": "Elle a reçu une amende pour stationnement illégal.",
    "p.b2-05.6": "Tout le monde est égal devant la loi.",
    "p.b2-05.7": "L'affaire a été classée faute de preuves.",
    "p.b2-05.8": "C'est seulement légal, ça ?",
    "p.b2-05.9": "L'avocat a exhorté son client à garder le silence.",
    "p.b2-05.10": "Vous avez le droit de garder le silence.",
    "p.b2-05.11": "L'accusé a été déclaré non coupable.",
    "s.b2-05.1": "L'accusé a affirmé qu'il avait été chez lui cette nuit-là.",
    "s.b2-05.2": "Le témoin a admis qu'elle n'avait pas vu le visage de l'homme.",
    "s.b2-05.3": "Le juge a demandé au témoin si elle reconnaissait l'accusé.",
    "s.b2-05.4": "L'avocat a insisté sur le fait que son client était innocent de fraude.",
    "s.b2-05.5": "La police a averti les habitants de ne pas laisser leurs portes ouvertes.",
    "s.b2-05.6": "L'entreprise a été poursuivie pour avoir enfreint les règlements sur la vie privée.",
    "s.b2-05.7": "Le ministre a nié que la nouvelle législation limiterait un quelconque droit.",
    "s.b2-05.8": "Le tribunal a jugé que l'interdiction de la manifestation était inconstitutionnelle.",
    "s.b2-05.9": "Après le verdict, l'accusé a annoncé qu'il ferait appel.",
    "s.b2-05.10": "Chaque citoyen a droit à un procès équitable en vertu de la constitution.",
    "s.b2-05.11": "L'enquête a révélé des preuves de discrimination envers les travailleurs âgés.",
    "s.b2-05.12": "Le reporter a dit que l'homme avait été condamné pour un crime grave.",
    "d.b2-05.1": "Noa, vous étiez dans la salle d'audience ce matin. Que s'est-il passé ?",
    "d.b2-05.2": "Le procès a commencé avec la présentation par l'accusation de nouvelles preuves contre l'accusé.",
    "d.b2-05.3": "Qu'a dit l'accusé ?",
    "d.b2-05.4": "Il a insisté sur le fait qu'il était innocent et a affirmé que les documents avaient été falsifiés.",
    "d.b2-05.5": "Des témoins ont-ils témoigné ?",
    "d.b2-05.6": "Oui. Une ancienne employée a admis qu'elle avait signé les contrats sans les lire.",
    "d.b2-05.7": "Comment le juge a-t-il réagi ?",
    "d.b2-05.8": "Il a averti les deux parties de ne pas parler à la presse et a demandé si d'autres preuves seraient présentées.",
    "d.b2-05.9": "Un verdict est-il attendu bientôt ?",
    "d.b2-05.10": "Les avocats m'ont dit que le procès durerait probablement encore trois semaines.",
    "d.b2-05.11": "Et s'il est condamné pour fraude ?",
    "d.b2-05.12": "Son avocat a déjà annoncé qu'ils feraient appel.",
    "m.b2-05": "Le procès de ... a commencé le ... . L'accusé a nié ... et a affirmé que ... . Un témoin a admis que ... . Le juge a averti ... . L'avocat a insisté sur le fait que ... et a annoncé que ... .",

