    "w.b2-06.vulnerable": "vulnérable",
    "w.b2-06.to-flee": "fuir",
    "p.b2-06.1": "C'est un problème mondial qui demande une solution mondiale.",
    "p.b2-06.2": "Nous devons sensibiliser les gens.",
    "p.b2-06.3": "Des millions de personnes n'ont pas accès à l'eau potable.",
    "p.b2-06.4": "Penser global, agir local.",
    "p.b2-06.5": "L'écart entre riches et pauvres se creuse.",
    "p.b2-06.6": "Le temps presse.",
    "p.b2-06.7": "Chaque don compte, aussi petit soit-il.",
    "p.b2-06.8": "Les négociations se sont terminées sans accord.",
    "p.b2-06.9": "C'est une goutte d'eau dans l'océan.",
    "p.b2-06.10": "Nous ne pouvons pas nous permettre de l'ignorer.",
    "p.b2-06.11": "Mieux vaut prévenir que guérir.",
    "s.b2-06.1": "Face à une grave sécheresse, le gouvernement a demandé une aide humanitaire.",
    "s.b2-06.2": "Signé en 2015, le traité vise à limiter le réchauffement climatique.",
    "s.b2-06.3": "Faire un don à une association caritative est une façon de s'attaquer à l'inégalité.",
    "s.b2-06.4": "Ayant fui le conflit, les familles vivent maintenant dans des abris provisoires.",
    "s.b2-06.5": "La déforestation détruit la biodiversité, affectant des millions d'espèces.",
    "s.b2-06.6": "Les sanctions imposées l'année dernière ont eu de graves conséquences.",
    "s.b2-06.7": "Se propageant rapidement au-delà des frontières, la pandémie a touché tous les pays.",
    "s.b2-06.8": "Les militants espèrent que la sensibilisation mènera à un vrai changement.",
    "s.b2-06.9": "L'ambassadeur a averti que la diplomatie seule ne mettrait pas fin au conflit.",
    "s.b2-06.10": "Améliorer les infrastructures est essentiel au développement des régions pauvres.",
    "s.b2-06.11": "Les populations vulnérables souffrent le plus des effets de la mondialisation.",
    "s.b2-06.12": "Sans accès à l'éducation, les enfants restent prisonniers de la pauvreté.",
    "d.b2-06.1": "Docteur Mansour, quelle est la gravité de la menace du réchauffement climatique aujourd'hui ?",
    "d.b2-06.2": "Extrêmement grave. Ayant étudié les données pendant vingt ans, je peux dire que les changements sont plus rapides que prévu.",
    "d.b2-06.3": "Yonatan, votre organisation se concentre sur la déforestation. Pourquoi ?",
    "d.b2-06.4": "Parce qu'abattre les forêts détruit la biodiversité et libère du carbone en même temps.",
    "d.b2-06.5": "Que peuvent faire les gens ordinaires ?",
    "d.b2-06.6": "Faire un don aide, mais sensibiliser et voter pour les bonnes politiques compte davantage.",
    "d.b2-06.7": "Je suis d'accord. Les gouvernements réagissent à la pression, comme on l'a vu avec le traité signé l'année dernière.",
    "d.b2-06.8": "Certains soutiennent que des sanctions contre les pays pollueurs seraient plus efficaces.",
    "d.b2-06.9": "Imposer des sanctions sans offrir d'aide nuit généralement aux populations les plus vulnérables.",
    "d.b2-06.10": "Exactement. La diplomatie et le développement doivent aller de pair.",
    "d.b2-06.11": "Y a-t-il une raison d'espérer ?",
    "d.b2-06.12": "Oui. Les énergies renouvelables se propagent plus vite que quiconque ne l'imaginait il y a dix ans.",
    "m.b2-06": "Ayant identifié ... comme une menace majeure, nous proposons ... . Financé par ..., le projet permettrait de ... . En travaillant avec les communautés locales, nous visons à ... . Réduire ... permettra aussi de ... .",

    "w.c1-01.claim": "l'affirmation",
    "w.c1-01.premise": "la prémisse",
    "w.c1-01.conclusion": "la conclusion",
    "w.c1-01.to-refute": "réfuter",
    "w.c1-01.to-concede": "concéder",
    "w.c1-01.counterargument": "le contre-argument",
    "w.c1-01.fallacy": "le sophisme",
    "w.c1-01.bias": "le biais",
    "w.c1-01.persuasive": "convaincant",
    "w.c1-01.to-justify": "justifier",
    "w.c1-01.coherent": "cohérent",
    "w.c1-01.contradiction": "la contradiction",
    "w.c1-01.to-assume": "supposer",
    "w.c1-01.stance": "la position",
    "w.c1-01.controversial": "controversé",
    "w.c1-01.to-undermine": "saper",
    "w.c1-01.to-acknowledge": "reconnaître",
    "w.c1-01.to-advocate": "préconiser",
    "w.c1-01.opponent": "l'adversaire",
    "w.c1-01.consensus": "le consensus",
    "w.c1-01.debate": "le débat",
    "w.c1-01.to-outweigh": "l'emporter sur",
    "w.c1-01.nevertheless": "néanmoins",
    "w.c1-01.whereas": "tandis que",
    "p.c1-01.1": "C'est une remarque juste, mais elle passe à côté de l'essentiel.",
    "p.c1-01.2": "Certes, les preuves sont limitées.",
    "p.c1-01.3": "Laissez-moi jouer l'avocat du diable un instant.",
    "p.c1-01.4": "Je comprends votre point de vue, mais je ne suis pas convaincu.",
    "p.c1-01.5": "Corrélation n'est pas causalité.",
    "p.c1-01.6": "Vous vous contredisez.",
    "p.c1-01.7": "Restons chacun sur nos positions.",
    "p.c1-01.8": "C'est à vous qu'incombe la charge de la preuve.",
    "p.c1-01.9": "Cet argument ne tient tout simplement pas debout.",
    "p.c1-01.10": "Avec tout le respect que je vous dois, ce n'est pas la question.",
    "p.c1-01.11": "Ce qui compte ici, c'est l'effet à long terme.",
    "p.c1-01.12": "Tout bien pesé, les avantages l'emportent sur les coûts.",
    "s.c1-01.1": "Bien que son affirmation semble convaincante, la prémisse qui la sous-tend est fausse.",
    "s.c1-01.2": "Certes, la politique est controversée ; néanmoins, elle a réduit la pauvreté.",
    "s.c1-01.3": "C'est le manque de preuves qui sape tout son argument.",
    "s.c1-01.4": "Je concède ce point, tandis que la conclusion, je la rejette toujours.",
    "s.c1-01.5": "Une position cohérente reconnaît les contre-arguments au lieu de les ignorer.",
    "s.c1-01.6": "Même si nous supposons de bonnes intentions, le biais affecte chaque décision.",
    "s.c1-01.7": "Ce qui rend un sophisme dangereux, c'est qu'il paraît logique.",
    "s.c1-01.8": "Elle a réfuté l'affirmation de son adversaire avec une seule statistique.",
    "s.c1-01.9": "Préconiser le changement est facile ; en justifier les coûts est plus difficile.",
    "s.c1-01.10": "Il y a une contradiction évidente entre sa prémisse et sa conclusion.",
    "s.c1-01.11": "Le consensus scientifique ne signifie pas que le débat est clos pour toujours.",
    "s.c1-01.12": "Au contraire, les données renforcent l'affirmation plutôt qu'elles ne l'affaiblissent.",
    "d.c1-01.1": "Omri, vous défendez le vote obligatoire. Votre affirmation d'ouverture, s'il vous plaît.",
    "d.c1-01.2": "La démocratie repose sur la participation. Quand la moitié de la population reste chez elle, le résultat reflète un échantillon biaisé, et non la volonté du peuple.",
    "d.c1-01.3": "Leah, votre réponse.",
    "d.c1-01.4": "Certes, la faible participation est un problème. Néanmoins, forcer les gens à voter sape la liberté même que les élections sont censées protéger.",
    "d.c1-01.5": "Je concède que la liberté compte. Cependant, nous acceptons déjà les impôts obligatoires et le devoir de juré, tandis que voter prend dix minutes.",
    "d.c1-01.6": "C'est une fausse comparaison. Les impôts financent des services ; un vote forcé produit des choix aléatoires par des électeurs mal informés.",
    "d.c1-01.7": "Omri, comment répondez-vous au contre-argument sur les électeurs mal informés ?",
    "d.c1-01.8": "Ce que montrent les données venues d'Australie, c'est que le vote obligatoire augmente en fait les connaissances politiques avec le temps.",
    "d.c1-01.9": "Un seul pays ne fait guère un consensus. D'ailleurs, vous supposez que l'effet serait le même ici.",
    "d.c1-01.10": "Certes, mais l'alternative, ne rien faire, a clairement échoué.",
    "d.c1-01.11": "Déclarations finales. Leah d'abord.",
    "d.c1-01.12": "Tout bien pesé, le coût pour la liberté l'emporte sur des avantages incertains. Persuadez les gens de voter ; ne les forcez pas.",
    "m.c1-01": "On affirme souvent que ... . Certes, ... . Néanmoins, ce que montrent les données, c'est que ... . Tandis que les opposants soutiennent que ..., cela néglige ... . Tout bien pesé, ... .",

    "w.c1-02.cognitive": "cognitif",
