    "w.c1-02.self-esteem": "l'estime de soi",
    "w.c1-02.reward": "la récompense",
    "w.c1-02.incentive": "l'incitation",
    "w.c1-02.prejudice": "le préjugé",
    "w.c1-02.stereotype": "le stéréotype",
    "w.c1-02.peer-pressure": "la pression du groupe",
    "w.c1-02.manipulation": "la manipulation",
    "w.c1-02.procrastination": "la procrastination",
    "w.c1-02.mindset": "l'état d'esprit",
    "w.c1-02.therapy": "la thérapie",
    "w.c1-02.willpower": "la volonté",
    "w.c1-02.to-repress": "refouler",
    "w.c1-02.rational": "rationnel",
    "p.c1-02.1": "C'est dans ta tête.",
    "p.c1-02.2": "Les vieilles habitudes ont la vie dure.",
    "p.c1-02.3": "Elle a tendance à trop réfléchir.",
    "p.c1-02.4": "Le stress a probablement joué un rôle.",
    "p.c1-02.5": "Il devait être sous une pression énorme.",
    "p.c1-02.6": "Dans une certaine mesure, nous avons tous des biais.",
    "p.c1-02.7": "Je n'ai pas pu résister à la tentation.",
    "p.c1-02.8": "Il semble que les récompenses fonctionnent mieux que les punitions.",
    "p.c1-02.9": "Ne tire pas de conclusions hâtives.",
    "p.c1-02.10": "On peut soutenir que la personnalité est davantage façonnée par l'environnement que par les gènes.",
    "p.c1-02.11": "Tu ne pouvais pas le savoir à ce moment-là.",
    "s.c1-02.1": "Les personnes ayant une haute estime de soi gèrent peut-être mieux la critique.",
    "s.c1-02.2": "La procrastination semble liée à l'anxiété plutôt qu'à la paresse.",
    "s.c1-02.3": "Les personnes extraverties tendent à rechercher des récompenses dans les situations sociales.",
    "s.c1-02.4": "Le sujet a peut-être refoulé le souvenir pendant des années.",
    "s.c1-02.5": "La pression du groupe pourrait expliquer, dans une certaine mesure, pourquoi les adolescents prennent des risques.",
    "s.c1-02.6": "Notre perception est sans doute façonnée par des préjugés subconscients.",
    "s.c1-02.7": "Les incitations ne fonctionnent probablement que lorsque l'objectif semble atteignable.",
    "s.c1-02.8": "La résilience semble dépendre en partie des premières relations.",
    "s.c1-02.9": "Il n'a pas pu agir par impulsion ; le plan était trop détaillé.",
    "s.c1-02.10": "La thérapie peut aider les patients à reconnaître la manipulation dans leurs relations.",
    "s.c1-02.11": "L'intuition n'est pas toujours irrationnelle ; elle reflète souvent l'expérience.",
    "s.c1-02.12": "Un état d'esprit de croissance améliore apparemment les performances cognitives des enfants.",
    "d.c1-02.1": "Docteur Peretz, pourquoi des gens intelligents prennent-ils des décisions irrationnelles ?",
    "d.c1-02.2": "L'intelligence et la rationalité sont des traits différents. Les gens intelligents sont peut-être simplement plus doués pour justifier leurs impulsions.",
    "d.c1-02.3": "Donc la volonté n'est pas la solution ?",
    "d.c1-02.4": "Seulement dans une certaine mesure. La volonté tend à s'épuiser ; un environnement favorable semble compter davantage.",
    "d.c1-02.5": "Vos recherches sur la procrastination ont surpris beaucoup de gens.",
    "d.c1-02.6": "Probablement parce que nous supposons que les procrastinateurs sont paresseux. Nos données suggèrent qu'il s'agit souvent de perfectionnistes anxieux.",
    "d.c1-02.7": "Les réseaux sociaux pourraient-ils aggraver la situation ?",
    "d.c1-02.8": "C'est possible. La comparaison constante semble diminuer l'estime de soi, surtout chez les adolescents exposés à la pression du groupe.",
    "d.c1-02.9": "Y a-t-il quelque chose qui construit la résilience de manière fiable ?",
    "d.c1-02.10": "Sans doute l'empathie d'un adulte de confiance. Les preuves ne sont pas concluantes, mais elles sont cohérentes.",
    "d.c1-02.11": "Un dernier conseil pour nos lecteurs ?",
    "d.c1-02.12": "Traitez votre intuition comme une hypothèse, pas comme un verdict. Puis vérifiez-la.",
    "m.c1-02": "Les recherches suggèrent que ... tend à ... . Cela peut s'expliquer par ... . Dans une certaine mesure, ... . Il semble que ..., bien que les preuves soient ... . Probablement, ... .",

    "w.c1-03.empire": "l'empire",
    "w.c1-03.revolution": "la révolution",
