    "w.c1-03.ethics": "l'éthique",
    "w.c1-03.morality": "la morale",
    "w.c1-03.virtue": "la vertu",
    "w.c1-03.enlightenment": "les Lumières",
    "w.c1-03.existence": "l'existence",
    "w.c1-03.skepticism": "le scepticisme",
    "w.c1-03.ideology": "l'idéologie",
    "w.c1-03.free-will": "le libre arbitre",
    "w.c1-03.to-contemplate": "méditer sur",
    "w.c1-03.paradox": "le paradoxe",
    "w.c1-03.to-interpret": "interpréter",
    "w.c1-03.turning-point": "le tournant",
    "p.c1-03.1": "L'histoire se répète.",
    "p.c1-03.2": "Ceux qui oublient le passé sont condamnés à le revivre.",
    "p.c1-03.3": "Cela a marqué un tournant dans l'histoire européenne.",
    "p.c1-03.4": "Avec le recul, l'effondrement était inévitable.",
    "p.c1-03.5": "La fin justifie les moyens, ou pas ?",
    "p.c1-03.6": "Je pense, donc je suis.",
    "p.c1-03.7": "Connais-toi toi-même.",
    "p.c1-03.8": "Cela soulève plus de questions que cela n'en résout.",
    "p.c1-03.9": "L'histoire est écrite par les vainqueurs.",
    "p.c1-03.10": "Non seulement l'empire est tombé, mais sa langue a disparu aussi.",
    "p.c1-03.11": "Le libre arbitre existe-t-il vraiment ?",
    "s.c1-03.1": "Jamais auparavant un empire ne s'était effondré aussi vite et aussi complètement.",
    "s.c1-03.2": "Non seulement la révolution a mis fin à l'esclavage, mais elle a aussi redéfini la citoyenneté.",
    "s.c1-03.3": "Parce que les archives ont été détruites, les historiens doivent interpréter des fragments.",
    "s.c1-03.4": "Ce n'est qu'après l'indépendance que le pays a commencé à écrire sa propre histoire.",
    "s.c1-03.5": "Les philosophes antiques se demandaient si la vertu pouvait s'enseigner.",
    "s.c1-03.6": "Bien que la raison guide l'éthique, l'émotion décide souvent de notre morale.",
    "s.c1-03.7": "Si le roi n'avait pas été renversé, l'ère des empires aurait pu continuer.",
    "s.c1-03.8": "Le scepticisme, loin de nier la connaissance, demande comment nous la justifions.",
    "s.c1-03.9": "L'idéologie était si puissante que des millions de personnes l'ont acceptée sans la remettre en question.",
    "s.c1-03.10": "Le paradoxe du libre arbitre, c'est que nous nous sentons libres tout en agissant de façon prévisible.",
    "s.c1-03.11": "Chaque civilisation qui a conquis ses voisins a fini par connaître le même sort.",
    "s.c1-03.12": "Ce que les philosophes appellent existence, les historiens l'appellent contexte.",
    "d.c1-03.1": "Pourquoi l'Empire romain s'est-il effondré ? Shai, commençons par vous.",
    "d.c1-03.2": "Traditionnellement, les historiens accusaient les invasions. Non seulement les frontières étaient trop longues, mais l'armée était aussi épuisée.",
    "d.c1-03.3": "Mor, vous n'êtes pas d'accord ?",
    "d.c1-03.4": "En partie. Si l'économie avait été saine, l'empire aurait pu survivre aux invasions, comme il l'avait fait auparavant.",
    "d.c1-03.5": "Vous interprétez donc l'effondrement comme économique plutôt que militaire ?",
    "d.c1-03.6": "Oui. L'esclavage rendait l'innovation inutile, et quand les conquêtes ont cessé, l'approvisionnement en esclaves aussi.",
    "d.c1-03.7": "C'est pourtant une lecture moderne. Les auteurs antiques eux-mêmes accusaient une perte de vertu.",
    "d.c1-03.8": "Ce qui soulève une question philosophique : une civilisation peut-elle décliner moralement ?",
    "d.c1-03.9": "Seulement si nous supposons que la morale est plus qu'une idéologie, ce que les sceptiques nieraient.",
    "d.c1-03.10": "Pourtant, sans une éthique commune, aucune société ne tient longtemps.",
    "d.c1-03.11": "Excellent. Pour la semaine prochaine, lisez les sources d'archives et décidez quel tournant vous semble le plus convaincant.",
    "d.c1-03.12": "Et si la chute était inévitable, ou si le libre arbitre a joué un rôle.",
    "m.c1-03": "Rarement une question a-t-elle divisé les penseurs aussi profondément que ... . Tandis que certains soutiennent que ..., d'autres estiment que ... . Non seulement cela importe pour ..., mais cela ... aussi. Ce n'est qu'en ... que nous pouvons ... .",

